package fr.formation.modular.reservation;
import java.time.LocalDateTime; import java.util.UUID; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/reservations") class ReservationApi { private final ReservationModule module; ReservationApi(ReservationModule module){this.module=module;} @PostMapping @ResponseStatus(HttpStatus.CREATED) ReservationModule.ReservationView create(@RequestBody Request r){return module.create(r.roomId(),r.organizerEmail(),r.participants(),r.startsAt(),r.endsAt());} @GetMapping("/{id}") ReservationModule.ReservationView get(@PathVariable UUID id){return module.get(id);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void cancel(@PathVariable UUID id){module.cancel(id);} record Request(UUID roomId,String organizerEmail,int participants,LocalDateTime startsAt,LocalDateTime endsAt){} }
